// Cảnh báo khi xuất bản bị tắt, có kỳ disputed, hoặc dữ liệu trễ > 2 ngày.
const health = $input.first().json;
const alerts = [];
if (health.publish_enabled === false) {
  alerts.push('publish_enabled = 0: website đang ngừng nhận dữ liệu mới.');
}
if (health.index_enabled === false) {
  alerts.push('index_enabled = 0: site đang noindex (deploy tối) — robots chặn, sitemap rỗng.');
}
for (const row of health.stale ?? []) {
  alerts.push(`Đài ${row.name} trễ ${row.lag_days === null ? 'chưa có bản xác nhận' : row.lag_days + ' ngày'}.`);
}
for (const row of health.stations ?? []) {
  if (row.disputed > 0) alerts.push(`Đài ${row.name} có ${row.disputed} kỳ disputed.`);
  if (row.pending > 0) alerts.push(`Đài ${row.name} có ${row.pending} kỳ chưa đối soát.`);
}
if (alerts.length === 0) return [];
return [{ json: { text: `[xoso] ${alerts.join(' | ')}`, checked_at: health.checked_at } }];
